from __future__ import annotations

import asyncio
import functools
import inspect
import random
import time
from collections.abc import Awaitable, Callable
from typing import Any, ParamSpec, TypeVar

P = ParamSpec("P")
R = TypeVar("R")


def retry(
    exceptions: type[BaseException] | tuple[type[BaseException], ...],
    attempts: int,
    max_delay: float,
) -> Callable[[Callable[P, R]], Callable[P, R]]:
    """
    Decorate a callable to retry on specified exceptions using exponential
    backoff with full jitter, capped by ``max_delay``.

    The wrapped callable may be synchronous or asynchronous. Delays are drawn
    uniformly from ``[0, min(max_delay, 2 ** (attempt_number - 1))]`` for each
    retry, where ``attempt_number`` is 1-based.

    Args:
        exceptions: Exception type or tuple of exception types that should
            trigger a retry.
        attempts: Total number of attempts, including the first call.
        max_delay: Maximum backoff delay in seconds.

    Returns:
        A decorator preserving the wrapped callable's metadata and signature.

    Raises:
        ValueError: If ``attempts < 1`` or ``max_delay < 0``.
        TypeError: If ``exceptions`` is not an exception type or tuple of them.
    """
    if attempts < 1:
        raise ValueError("attempts must be at least 1")
    if max_delay < 0:
        raise ValueError("max_delay must be non-negative")

    normalized_exceptions = _normalize_exceptions(exceptions)

    def decorator(func: Callable[P, R]) -> Callable[P, R]:
        if inspect.iscoroutinefunction(func):

            @functools.wraps(func)
            async def async_wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
                for attempt_number in range(1, attempts + 1):
                    try:
                        result = func(*args, **kwargs)
                        return await _await_result(result)
                    except normalized_exceptions:
                        if attempt_number >= attempts:
                            raise
                        delay = _compute_delay(attempt_number, max_delay)
                        await asyncio.sleep(delay)
                raise AssertionError("unreachable")

            return async_wrapper

        @functools.wraps(func)
        def sync_wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
            for attempt_number in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except normalized_exceptions:
                    if attempt_number >= attempts:
                        raise
                    delay = _compute_delay(attempt_number, max_delay)
                    time.sleep(delay)
            raise AssertionError("unreachable")

        return sync_wrapper

    return decorator


def _normalize_exceptions(
    exceptions: type[BaseException] | tuple[type[BaseException], ...],
) -> tuple[type[BaseException], ...]:
    if isinstance(exceptions, tuple):
        if not exceptions:
            raise TypeError("exceptions tuple must not be empty")
        normalized = exceptions
    else:
        normalized = (exceptions,)

    for exc in normalized:
        if not isinstance(exc, type) or not issubclass(exc, BaseException):
            raise TypeError(
                "exceptions must be an exception type or a tuple of exception types"
            )
    return normalized


def _compute_delay(attempt_number: int, max_delay: float) -> float:
    upper_bound = min(max_delay, 2 ** (attempt_number - 1))
    return random.uniform(0.0, upper_bound)


async def _await_result(result: R | Awaitable[R]) -> R:
    if inspect.isawaitable(result):
        return await result
    return result

