import json
from json import JSONDecodeError
from typing import Any


class RecordIterator(Generator[Any, None, None]):
    """
    Generator-like iterator over newline-delimited JSON records.

    Successfully parsed JSON values are yielded one at a time.
    Malformed lines are collected in ``errors`` as ``(line_number, line)`` pairs
    and do not stop iteration.
    """

    def __init__(self, lines: Iterable[str]) -> None:
        self._iter = iter(lines)
        self._line_number = 0
        self.errors: list[tuple[int, str]] = []

    def __iter__(self) -> RecordIterator:
        return self

    def __next__(self) -> Any:
        for line in self._iter:
            self._line_number += 1
            try:
                return json.loads(line)
            except JSONDecodeError:
                self.errors.append((self._line_number, line))
                continue
        raise StopIteration

    def send(self, value: None) -> Any:
        if value is not None:
            raise TypeError(f"{type(self).__name__}.send() only accepts None")
        return self.__next__()

    def throw(
        self,
        typ: type[BaseException] | BaseException,
        val: BaseException | None = None,
        tb: object | None = None,
    ) -> Any:
        if isinstance(typ, BaseException):
            raise typ
        if val is None:
            raise typ
        raise val.with_traceback(tb if tb is not None else val.__traceback__)

    def close(self) -> None:
        return None


def iter_records(lines: Iterable[str]) -> RecordIterator:
    """
    Parse an iterable of newline-delimited JSON strings.

    Returns a generator-like iterator that yields each successfully parsed JSON
    value as it is read. Malformed lines are skipped and recorded in the
    returned object's ``errors`` attribute as ``(line_number, line)`` pairs.

    Example:
        records = iter_records(lines)
        for obj in records:
            ...
        bad_lines = records.errors
    """
    return RecordIterator(lines)
