from __future__ import annotations

import re
from dataclasses import dataclass, field
from functools import total_ordering
from typing import Final


_SEMVER_RE: Final[re.Pattern[str]] = re.compile(
    r"""
    ^
    (?P<major>0|[1-9]\d*)
    \.
    (?P<minor>0|[1-9]\d*)
    \.
    (?P<patch>0|[1-9]\d*)
    (?:-(?P<prerelease>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?
    (?:\+(?P<build>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?
    $
    """,
    re.VERBOSE,
)


def _validate_identifiers(part: str, value: str, *, numeric_no_leading_zero: bool) -> tuple[str, ...]:
    identifiers = tuple(value.split("."))
    for identifier in identifiers:
        if not identifier:
            raise ValueError(f"invalid {part}: empty identifier")
        if not re.fullmatch(r"[0-9A-Za-z-]+", identifier):
            raise ValueError(f"invalid {part}: identifier {identifier!r} contains invalid characters")
        if numeric_no_leading_zero and identifier.isdigit() and len(identifier) > 1 and identifier[0] == "0":
            raise ValueError(
                f"invalid {part}: numeric identifier {identifier!r} must not contain leading zeroes"
            )
    return identifiers


@total_ordering
@dataclass(frozen=True, slots=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = field(default_factory=tuple)
    build: tuple[str, ...] = field(default_factory=tuple)

    def __post_init__(self) -> None:
        for name, value in (("major", self.major), ("minor", self.minor), ("patch", self.patch)):
            if value < 0:
                raise ValueError(f"invalid {name}: must be non-negative")

        object.__setattr__(
            self,
            "prerelease",
            _validate_identifiers("prerelease", ".".join(self.prerelease), numeric_no_leading_zero=True)
            if self.prerelease
            else (),
        )
        object.__setattr__(
            self,
            "build",
            _validate_identifiers("build metadata", ".".join(self.build), numeric_no_leading_zero=False)
            if self.build
            else (),
        )

    @classmethod
    def parse(cls, text: str) -> Version:
        match = _SEMVER_RE.fullmatch(text)
        if match is None:
            cls._raise_parse_error(text)

        assert match is not None
        major_text = match.group("major")
        minor_text = match.group("minor")
        patch_text = match.group("patch")
        prerelease_text = match.group("prerelease")
        build_text = match.group("build")

        prerelease = (
            _validate_identifiers("prerelease", prerelease_text, numeric_no_leading_zero=True)
            if prerelease_text is not None
            else ()
        )
        build = (
            _validate_identifiers("build metadata", build_text, numeric_no_leading_zero=False)
            if build_text is not None
            else ()
        )

        return cls(
            major=int(major_text),
            minor=int(minor_text),
            patch=int(patch_text),
            prerelease=prerelease,
            build=build,
        )

    @staticmethod
    def _raise_parse_error(text: str) -> None:
        if not text:
            raise ValueError("invalid version: empty string")

        if "+" in text:
            main_part, build_part = text.split("+", 1)
            if "+" in build_part:
                raise ValueError("invalid build metadata: multiple '+' separators")
            if not build_part:
                raise ValueError("invalid build metadata: empty")
            _validate_identifiers("build metadata", build_part, numeric_no_leading_zero=False)
        else:
            main_part = text

        if "-" in main_part:
            core_part, prerelease_part = main_part.split("-", 1)
            if not prerelease_part:
                raise ValueError("invalid prerelease: empty")
            _validate_identifiers("prerelease", prerelease_part, numeric_no_leading_zero=True)
        else:
            core_part = main_part

        core = core_part.split(".")
        if len(core) != 3:
            raise ValueError("invalid core version: expected 'MAJOR.MINOR.PATCH'")

        for name, piece in zip(("major", "minor", "patch"), core, strict=True):
            if piece == "":
                raise ValueError(f"invalid {name}: empty")
            if not piece.isdigit():
                raise ValueError(f"invalid {name}: {piece!r} is not numeric")
            if len(piece) > 1 and piece[0] == "0":
                raise ValueError(f"invalid {name}: {piece!r} must not contain leading zeroes")

        raise ValueError("invalid version")

    def __str__(self) -> str:
        result = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            result += "-" + ".".join(self.prerelease)
        if self.build:
            result += "+" + ".".join(self.build)
        return result

    def __repr__(self) -> str:
        return f"Version.parse({str(self)!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return (
            self.major,
            self.minor,
            self.patch,
            self.prerelease,
        ) == (
            other.major,
            other.minor,
            other.patch,
            other.prerelease,
        )

    def __lt__(self, other: Version) -> bool:
        if not isinstance(other, Version):
            return NotImplemented

        self_core = (self.major, self.minor, self.patch)
        other_core = (other.major, other.minor, other.patch)
        if self_core != other_core:
            return self_core < other_core

        if not self.prerelease and not other.prerelease:
            return False
        if not self.prerelease:
            return False
        if not other.prerelease:
            return True

        return self._compare_prerelease(other) < 0

    def _compare_prerelease(self, other: Version) -> int:
        for left, right in zip(self.prerelease, other.prerelease):
            if left == right:
                continue

            left_is_num = left.isdigit()
            right_is_num = right.isdigit()

            if left_is_num and right_is_num:
                left_num = int(left)
                right_num = int(right)
                if left_num < right_num:
                    return -1
                return 1

