from typing import Any


class ListStrategy(str, Enum):
    REPLACE = "replace"
    APPEND = "append"
    APPEND_UNIQUE = "append_unique"


def merge(
    base: Mapping[str, Any],
    override: Mapping[str, Any],
    *,
    list_strategy: ListStrategy | str,
) -> dict[str, Any]:
    """
    Deeply merge two nested configuration dictionaries.

    Rules:
    - Nested dictionaries are merged recursively.
    - Lists are handled according to `list_strategy`:
      - REPLACE: override list replaces base list
      - APPEND: override items are appended to base items
      - APPEND_UNIQUE: override items are appended only if not already present
    - Inputs are not mutated.
    - If one side is a dictionary and the other is not, a TypeError is raised.

    Parameters
    ----------
    base:
        The base configuration mapping.
    override:
        The overriding configuration mapping.
    list_strategy:
        One of ListStrategy.REPLACE, ListStrategy.APPEND, or
        ListStrategy.APPEND_UNIQUE. String values matching those enum values
        are also accepted.

    Returns
    -------
    dict[str, Any]
        A new merged dictionary.
    """
    strategy = _normalize_list_strategy(list_strategy)
    return _merge_mapping(base, override, strategy, path=())


def _normalize_list_strategy(value: ListStrategy | str) -> ListStrategy:
    if isinstance(value, ListStrategy):
        return value
    try:
        return ListStrategy(value)
    except ValueError as exc:
        valid = ", ".join(item.value for item in ListStrategy)
        raise ValueError(f"Invalid list_strategy {value!r}. Expected one of: {valid}.") from exc


def _merge_mapping(
    base: Mapping[str, Any],
    override: Mapping[str, Any],
    list_strategy: ListStrategy,
    path: tuple[str, ...],
) -> dict[str, Any]:
    result: dict[str, Any] = {}

    for key in base.keys() | override.keys():
        in_base = key in base
        in_override = key in override

        if in_base and in_override:
            result[key] = _merge_value(base[key], override[key], list_strategy, path + (key,))
        elif in_base:
            result[key] = deepcopy(base[key])
        else:
            result[key] = deepcopy(override[key])

    return result


def _merge_value(
    base_value: Any,
    override_value: Any,
    list_strategy: ListStrategy,
    path: tuple[str, ...],
) -> Any:
    base_is_mapping = isinstance(base_value, Mapping)
    override_is_mapping = isinstance(override_value, Mapping)

    if base_is_mapping or override_is_mapping:
        if base_is_mapping and override_is_mapping:
            return _merge_mapping(base_value, override_value, list_strategy, path)
        raise TypeError(
            f"Type conflict at { _format_path(path) }: cannot merge mapping with non-mapping "
            f"({type(base_value).__name__} vs {type(override_value).__name__})."
        )

    base_is_list = isinstance(base_value, list)
    override_is_list = isinstance(override_value, list)

    if base_is_list and override_is_list:
        return _merge_list(base_value, override_value, list_strategy)

    return deepcopy(override_value)


def _merge_list(
    base_list: list[Any],
    override_list: list[Any],
    list_strategy: ListStrategy,
) -> list[Any]:
    if list_strategy is ListStrategy.REPLACE:
        return deepcopy(override_list)

    if list_strategy is ListStrategy.APPEND:
        return deepcopy(base_list) + deepcopy(override_list)

    if list_strategy is ListStrategy.APPEND_UNIQUE:
        result = deepcopy(base_list)
        for item in override_list:
            if item not in result:
                result.append(deepcopy(item))
        return result

    raise AssertionError(f"Unhandled list strategy: {list_strategy!r}")


def _format_path(path: Sequence[str]) -> str:
    if not path:
        return "<root>"
    return ".".join(path)

