import copy
from typing import Any, Dict, List, Literal, Union

ListStrategy = Literal["replace", "append", "append_unique"]


def merge(
    base: Dict[str, Any],
    override: Dict[str, Any],
    *,
    list_strategy: ListStrategy = "replace",
) -> Dict[str, Any]:
    """Deeply merges two nested configuration dictionaries.

    Args:
        base: The base dictionary to merge into.
        override: The dictionary with overrides.
        list_strategy: How to handle lists. Options are:
            - "replace": The list from `override` replaces the list from `base`.
            - "append": The list from `override` is appended to the list from `base`.
            - "append_unique": Elements from the list in `override` are appended to the
              list from `base` only if they are not already present.

    Returns:
        A new dictionary representing the merged configuration.

    Raises:
        TypeError: If a key's value is a dictionary in one input and a scalar
                   (non-dict, non-list) in the other.
    """
    if not isinstance(base, dict) or not isinstance(override, dict):
        raise TypeError("Both base and override must be dictionaries.")

    merged = copy.deepcopy(base)

    for key, override_value in override.items():
        base_value = merged.get(key)

        if isinstance(override_value, dict):
            if isinstance(base_value, dict):
                merged[key] = merge(base_value, override_value, list_strategy=list_strategy)
            elif base_value is None:
                merged[key] = copy.deepcopy(override_value)
            else:
                raise TypeError(
                    f"Cannot merge dictionary for key '{key}' with non-dictionary value "
                    f"of type {type(base_value).__name__} in base."
                )
        elif isinstance(override_value, list):
            if isinstance(base_value, list):
                if list_strategy == "replace":
                    merged[key] = copy.deepcopy(override_value)
                elif list_strategy == "append":
                    merged[key] = base_value + copy.deepcopy(override_value)
                elif list_strategy == "append_unique":
                    # Create a new list to avoid modifying the original base_value
                    new_list = list(base_value)
                    for item in override_value:
                        if item not in new_list:
                            new_list.append(item)
                    merged[key] = new_list
                else:
                    raise ValueError(
                        f"Unknown list_strategy: {list_strategy}. "
                        "Must be 'replace', 'append', or 'append_unique'."
                    )
            elif base_value is None:
                merged[key] = copy.deepcopy(override_value)
            else:
                raise TypeError(
                    f"Cannot merge list for key '{key}' with non-list value "
                    f"of type {type(base_value).__name__} in base."
                )
        else:  # Scalar override value
            if isinstance(base_value, dict):
                raise TypeError(
                    f"Cannot merge scalar for key '{key}' with dictionary value "
                    f"of type {type(base_value).__name__} in base."
                )
            elif isinstance(base_value, list):
                raise TypeError(
                    f"Cannot merge scalar for key '{key}' with list value "
                    f"of type {type(base_value).__name__} in base."
                )
            else:
                merged[key] = copy.deepcopy(override_value)

    return merged

