from collections import defaultdict
import heapq
from typing import Dict, Hashable, Iterable, List, Mapping, Set, TypeVar

T = TypeVar("T", bound=Hashable)


class CycleError(ValueError):
    """Raised when the dependency graph contains a cycle."""


def topological_sort(graph: Mapping[T, Iterable[T]]) -> List[T]:
    """
    Return a deterministic topological ordering for a dependency mapping.

    The input maps each node to the iterable of nodes it depends on.
    Nodes that appear only as dependencies are included in the result.

    Determinism:
        When multiple nodes are available to emit, the smallest node under
        a stable ordering is chosen. The ordering key is based on
        ``(type(node).__module__, type(node).__qualname__, repr(node))``.

    Cycle handling:
        If a cycle exists, a CycleError is raised whose message names one
        concrete cycle.

    Example:
        >>> topological_sort({"build": ["compile"], "compile": ["parse"]})
        ['parse', 'compile', 'build']
    """
    nodes: Set[T] = set(graph)
    dependencies: Dict[T, Set[T]] = {}

    for node, deps_iter in graph.items():
        deps = set(deps_iter)
        dependencies[node] = deps
        nodes.update(deps)

    for node in nodes:
        dependencies.setdefault(node, set())

    dependents: Dict[T, Set[T]] = defaultdict(set)
    indegree: Dict[T, int] = {}

    for node in nodes:
        indegree[node] = len(dependencies[node])
        for dep in dependencies[node]:
            dependents[dep].add(node)

    heap: List[tuple[tuple[str, str, str], T]] = []
    for node in nodes:
        if indegree[node] == 0:
            heapq.heappush(heap, (_sort_key(node), node))

    result: List[T] = []

    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        for dependent in sorted(dependents[node], key=_sort_key):
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, (_sort_key(dependent), dependent))

    if len(result) != len(nodes):
        cycle = _find_cycle(nodes, dependencies)
        if cycle:
            names = " -> ".join(repr(node) for node in cycle)
            raise CycleError(f"dependency cycle detected: {names}")
        raise CycleError("dependency cycle detected")

    return result


def _sort_key(node: T) -> tuple[str, str, str]:
    node_type = type(node)
    return (node_type.__module__, node_type.__qualname__, repr(node))


def _find_cycle(nodes: Set[T], dependencies: Mapping[T, Set[T]]) -> List[T] | None:
    visited: Set[T] = set()
    in_stack: Set[T] = set()
    stack: List[T] = []
    stack_index: Dict[T, int] = {}

    for start in sorted(nodes, key=_sort_key):
        if start not in visited:
            cycle = _dfs_find_cycle(
                start, dependencies, visited, in_stack, stack, stack_index
            )
            if cycle is not None:
                return cycle
    return None


def _dfs_find_cycle(
    node: T,
    dependencies: Mapping[T, Set[T]],
    visited: Set[T],
    in_stack: Set[T],
    stack: List[T],
    stack_index: Dict[T, int],
) -> List[T] | None:
    visited.add(node)
    in_stack.add(node)
    stack_index[node] = len(stack)
    stack.append(node)

    for dep in sorted(dependencies[node], key=_sort_key):
        if dep not in visited:
            cycle = _dfs_find_cycle(
                dep, dependencies, visited, in_stack, stack, stack_index
            )
            if cycle is not None:
                return cycle
        elif dep in in_stack:
            start = stack_index[dep]
            return stack[start:] + [dep]

    stack.pop()
    del stack_index[node]
    in_stack.remove(node)
    return None

