    """
    Mark a callable as deprecated.

    The resulting warning:
    - is emitted as a DeprecationWarning,
    - appears at the caller's line,
    - is shown once per distinct call site by the warnings machinery.

    Supports plain functions, instance methods, @classmethod, and @staticmethod.
    """

    def decorator(
        obj: F | staticmethod[F] | classmethod[F],
    ) -> F | staticmethod[F] | classmethod[F]:
        if isinstance(obj, staticmethod):
            func = cast(F, obj.__func__)
            return staticmethod(_wrap_function(func, reason))

        if isinstance(obj, classmethod):
            func = cast(F, obj.__func__)
            return classmethod(_wrap_function(func, reason))

        return _wrap_function(cast(F, obj), reason)

    return decorator
